begin;
create table public.incident_resources (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), incident_id uuid not null references public.incidents(id), resource_type text not null, resource_name text, callsign text, status text not null default 'deployed', deployed_at timestamptz not null default now(), notes text, recorded_by uuid not null references public.internal_users(id));
create table public.incident_agencies (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), incident_id uuid not null references public.incidents(id), agency text not null, contact_reference text, contacted_at timestamptz, on_scene_at timestamptz, notes text, recorded_by uuid not null references public.internal_users(id));
create table public.incident_people (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), incident_id uuid not null references public.incidents(id), person_role text not null, name text, description text, welfare_notes text, recorded_by uuid not null references public.internal_users(id));
create table public.incident_evidence (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), incident_id uuid not null references public.incidents(id), evidence_type text not null, reference text, description text, secured_at timestamptz, recorded_by uuid not null references public.internal_users(id), created_at timestamptz not null default now());
create table public.incident_escalations (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), incident_id uuid not null references public.incidents(id), notified_party text not null, escalated_at timestamptz not null default now(), reason text not null, outcome text, recorded_by uuid not null references public.internal_users(id));
create table public.incident_follow_up_actions (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id), incident_id uuid not null references public.incidents(id), action text not null, owner text, due_at timestamptz, status text not null default 'open', recorded_by uuid not null references public.internal_users(id));
alter table public.incident_resources enable row level security; alter table public.incident_agencies enable row level security; alter table public.incident_people enable row level security; alter table public.incident_evidence enable row level security; alter table public.incident_escalations enable row level security; alter table public.incident_follow_up_actions enable row level security;
revoke all on public.incident_resources,public.incident_agencies,public.incident_people,public.incident_evidence,public.incident_escalations,public.incident_follow_up_actions from anon,authenticated;
grant select,insert,update,delete on public.incident_resources,public.incident_agencies,public.incident_people,public.incident_evidence,public.incident_escalations,public.incident_follow_up_actions to service_role;
commit;
